    ms' = MS (mkR rax spx gp tp t0' t1' t2' s0 s1 a0' a1' a2' a3' a4' a5' a6' a7' s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 pc') fc None m1 (seg_rom rsegs)
    /\ ((pc' = 0x3bdc4 /\ a0' = wz bit) \/ pc' = 0x3bdd0).

Local Ltac cmp_done5c := apply evt_done; do 12 eexists; split; [reflexivity | left; split; reflexivity].
Local Ltac cmp_done68 := apply evt_done; do 12 eexists; split; [reflexivity | right; reflexivity].

Lemma lit_upgrade_len : length (litb LIT_UPGRADE) = 7%nat. Proof. reflexivity. Qed.
Lemma lit_close_len : length (litb LIT_CLOSE) = 5%nat. Proof. reflexivity. Qed.
Lemma lit_keepalive_len : length (litb LIT_KEEPALIVE) = 10%nat. Proof. reflexivity. Qed.

