(* [comment removed for export] *)
Lemma clo_fast : forall (r : nat) (i : Z) rax spx gp tp t0 t1 t2 s0 s1 a0 a2 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m1 : mem) (vp vq : Z) (vbs : list byte),
  bytes_at rsegs m1 vp vbs -> bytes_at rsegs m1 A_CLOSE (litb LIT_CLOSE) -> mem_inv rsegs m1 ->
  vp <= vq -> vq + 5 <= vp + Z.of_nat (length vbs) -> vp + Z.of_nat (length vbs) < 2^64 ->
  0 <= i -> i + Z.of_nat r = 5 ->
  evt rsegs (cmp_post rax spx gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m1 128)
    (MS (mkR rax spx gp tp t0 t1 t2 s0 s1 a0 (wz vq) a2 (wz (- i)) (wz (Z.of_nat r)) (wz (A_CLOSE + i)) (wz (vq + i)) a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
