(* [comment removed for export] *)
Lemma ka_fast : forall (r : nat) (i : Z) rax spx gp tp t0 t1 t2 s0 s1 a0 a1 a3 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m1 : mem) (vp vq : Z) (vbs : list byte),
  bytes_at rsegs m1 vp vbs -> bytes_at rsegs m1 A_KEEPALIVE (litb LIT_KEEPALIVE) -> mem_inv rsegs m1 ->
  vp <= vq -> vq + 10 <= vp + Z.of_nat (length vbs) -> vp + Z.of_nat (length vbs) < 2^64 ->
  0 <= i -> i + Z.of_nat r = 10 ->
  evt rsegs (cmp_post rax spx gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m1 512)
    (MS (mkR rax spx gp tp t0 t1 t2 s0 s1 a0 a1 (wz 10) a3 (wz (A_KEEPALIVE + i)) (wz (Z.of_nat r)) (wz (vq + i)) a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0x3bcc8) fc None m1 (seg_rom rsegs)).
