(* [comment removed for export] *)
(* [comment removed for export] *)
Section CONN.
  Hypothesis OPTI : optit_incr_stmt.
  Hypothesis VALID : validate_list_stmt.

Local Ltac dof_finish c' E' g' :=
  apply evt_done; unfold dof_post;
  do 16 eexists; exists c', E', g';
  split; [reflexivity|]; repeat match goal with |- _ /\ _ => split end; try fast_assumption; try lia.

Definition conn_ctx (m m1 : mem) (sp : word) (sv : list word) (P E lo : Z) (c : pcore) (pad7 pad2 : list byte) (f1 : Z)
    (vp : Z) (vbs : list byte) (j1 : list byte) (itc vq vl err : Z) (pad7o j3 : list byte) (e1 e2 e3 : word) (g : bool) : Prop :=
  rw_cells rsegs m1 (bv_unsigned sp + -288) [CB 152 j1]
  /\ rw_cells rsegs m1 (bv_unsigned sp + -136) (OptItCells (bv_unsigned sp + -96) itc vq vl err pad7o)
  /\ rw_cells rsegs m1 (bv_unsigned sp + -96) [C8 (wz vp); C8 (wz (Z.of_nat (length vbs)))]
  /\ rw_cells rsegs m1 (bv_unsigned sp + -80) [CB 8 j3]
  /\ rw_cells rsegs m1 (bv_unsigned sp + -72) (map C8 sv)
  /\ rw_cells rsegs m1 P (ParserCoreCells (mkPC (pc_blim_has c) (pc_blim c) (pc_len c) (pc_len0 c) (pc_skip c) (pc_hlim c) (pc_state c) f1) pad7 pad2)
  /\ rw_cells rsegs m1 E [C8 e1; C8 e2; C8 e3]
  /\ bytes_at rsegs m1 vp vbs
  /\ HttpCat m1 g /\ XStatics m1
  /\ stk rsegs m1 lo (bv_unsigned sp + -288)
  /\ munch (dof_W lo sp P E) m m1 /\ wmono rsegs m m1 /\ mem_inv rsegs m1.

Definition CONN_AT (B : Z) : Prop :=
  forall (itc vq vl err : Z) rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s3x s4x s5x s6x s7x
         s0v s1v s2v s3v s4v s5v s6v s7v s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P E lo : Z) (c : pcore) (pad7 pad2 : list byte) (f1 vp : Z) (vbs : list byte)
    (j1 pad7o j3 : list byte) (e1 e2 e3 : word) (g : bool),
  conn_ctx m m1 sp (dof_sv s7v s6v s5v s4v s3v s2v s1v s0v ra) P E lo c pad7 pad2 f1 vp vbs j1 itc vq vl err pad7o j3 e1 e2 e3 g ->
  dof_pure sp P E lo c (pc_state c) vp vbs -> 0 <= f1 < 2^14 ->
  vp <= vq -> 1 <= vl -> vq + vl = itc -> itc <= vp + Z.of_nat (length vbs) -> vp + Z.of_nat (length vbs) - itc < B ->
  evt rsegs (dof_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8 s9 s10 s11 F fc P E lo c pad7 pad2 vp vbs m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -288)) gp tp t0 t1 t2 (wz E) (wz P) a0 a1 a2 a3 a4 a5 a6 a7
              (Z_to_bv 64 (bv_unsigned sp + -96)) s3x s4x s5x s6x s7x s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0x3bc0c) fc None m1 (seg_rom rsegs)).

(* [comment removed for export] *)
Lemma conn_ret : forall (optc : list cell) rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s2x s3x s4x s5x s6x s7x
         s0v s1v s2v s3v s4v s5v s6v s7v s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P E lo : Z) (c : pcore) (pad7 pad2 : list byte) (f1 vp : Z) (vbs : list byte)
    (j1 j3 : list byte) (e1 e2 e3 : word) (g : bool),
  rw_cells rsegs m1 (bv_unsigned sp + -288) [CB 152 j1] ->
  rw_cells rsegs m1 (bv_unsigned sp + -136) optc -> cells_size optc = 40%nat ->
  rw_cells rsegs m1 (bv_unsigned sp + -96) [C8 (wz vp); C8 (wz (Z.of_nat (length vbs)))] ->
  rw_cells rsegs m1 (bv_unsigned sp + -80) [CB 8 j3] ->
  rw_cells rsegs m1 (bv_unsigned sp + -72) (map C8 (dof_sv s7v s6v s5v s4v s3v s2v s1v s0v ra)) ->
  rw_cells rsegs m1 P (ParserCoreCells (mkPC (pc_blim_has c) (pc_blim c) (pc_len c) (pc_len0 c) (pc_skip c) (pc_hlim c) (pc_state c) f1) pad7 pad2) ->
  rw_cells rsegs m1 E [C8 e1; C8 e2; C8 e3] ->
  bytes_at rsegs m1 vp vbs -> HttpCat m1 g -> XStatics m1 -> stk rsegs m1 lo (bv_unsigned sp + -288) ->
  munch (dof_W lo sp P E) m m1 -> wmono rsegs m m1 -> mem_inv rsegs m1 ->
  dof_pure sp P E lo c (pc_state c) vp vbs -> 0 <= f1 < 2^14 ->
  evt rsegs (dof_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8 s9 s10 s11 F fc P E lo c pad7 pad2 vp vbs m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -288)) gp tp t0 t1 t2 (wz E) (wz P) a0 a1 a2 a3 a4 a5 a6 a7
              s2x s3x s4x s5x s6x s7x s8 s9 s10 s11 t3 t4 t5 t6)
