(* [comment removed for export] *)
Lemma up_fast0 : forall rax spx gp tp t0 t1 t2 s0 s1 a0 a2 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m1 : mem) (vp vq : Z) (vbs : list byte),
  bytes_at rsegs m1 vp vbs -> bytes_at rsegs m1 A_UPGRADE (litb LIT_UPGRADE) -> mem_inv rsegs m1 ->
  vp <= vq -> vq + 7 <= vp + Z.of_nat (length vbs) -> vp + Z.of_nat (length vbs) < 2^64 ->
  evt rsegs (cmp_post rax spx gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m1 256)
    (MS (mkR rax spx gp tp t0 t1 t2 s0 s1 a0 (wz vq) a2 (wz 0) (wz A_UPGRADE) (wz 7) (wz vq) a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0x3bc40) fc None m1 (seg_rom rsegs)).
Proof.
  intros rax spx gp tp t0 t1 t2 s0 s1 a0 a2 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m1 vp vq vbs WIN LIT MI V1 V2 V3.
  pose proof (up_fast 7 0 rax spx gp tp t0 t1 t2 s0 s1 a0 a2 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m1 vp vq vbs
                WIN LIT MI V1 V2 V3 ltac:(lia) ltac:(reflexivity)) as K.
  rewrite !Z.add_0_r in K. exact K.
Qed.
Lemma clo_fast0 : forall rax spx gp tp t0 t1 t2 s0 s1 a0 a2 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m1 : mem) (vp vq : Z) (vbs : list byte),
  bytes_at rsegs m1 vp vbs -> bytes_at rsegs m1 A_CLOSE (litb LIT_CLOSE) -> mem_inv rsegs m1 ->
  vp <= vq -> vq + 5 <= vp + Z.of_nat (length vbs) -> vp + Z.of_nat (length vbs) < 2^64 ->
  evt rsegs (cmp_post rax spx gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m1 128)
    (MS (mkR rax spx gp tp t0 t1 t2 s0 s1 a0 (wz vq) a2 (wz 0) (wz 5) (wz A_CLOSE) (wz vq) a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0x3bd4c) fc None m1 (seg_rom rsegs)).
Proof.
  intros rax spx gp tp t0 t1 t2 s0 s1 a0 a2 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m1 vp vq vbs WIN LIT MI V1 V2 V3.
  pose proof (clo_fast 5 0 rax spx gp tp t0 t1 t2 s0 s1 a0 a2 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m1 vp vq vbs
                WIN LIT MI V1 V2 V3 ltac:(lia) ltac:(reflexivity)) as K.
